// Sklada `data` dla file-renderer-service (kontrakt: file-renderer-service/test_schema_v4_contract.py).
// Wyjatek od "Set zamiast Code": grupowanie powiazanych rekordow po id rodzica.
const offer = $('Offer from button').first().json.offer;
const rows = (name) => $(name).all().map(i => i.json).filter(j => j && j.id_fields && j.id_fields.Id);
const accepted = (f) => f && f.ai_status === 'ai_accepted';
const warnings = [];

const recs = rows('Get linked recommendations').sort((a, b) => a.id_fields.Id - b.id_fields.Id);
const people = rows('Participant with recommendation');
const asses = rows('Assessment with participant');
const cores = rows('Core with recommendation');
const slides = rows('Slide with core').sort((a, b) => a.id_fields.Id - b.id_fields.Id);
const selOthers = rows('Get linked selected others');
const variants = rows('Variant with selection');
const testimonialRows = rows('Get linked testimonials').sort((a, b) => a.id_fields.Id - b.id_fields.Id);

// uczestnicy: osoby z rekomendacji, bez duplikatow
const seen = new Set();
const participants = [];
for (const rec of recs) {
  const p = people.find(x => x._rec_id === rec.id_fields.Id);
  if (!p || seen.has(p.id_fields.Id)) continue;
  seen.add(p.id_fields.Id);
  participants.push({ person: p, rec });
}
if (!participants.length) warnings.push('Brak uczestnikow: rekomendacje nie maja podlinkowanej osoby.');

// pierwsza osoba: ocena + rekomendacja (tylko tekst AI ze statusem ai_accepted)
const first = participants[0];
let assessment = {}, a = {}, recommendation = {};
if (first) {
  const mine = asses.filter(x => x._person_id === first.person.id_fields.Id)
    .sort((x, y) => y.id_fields.Id - x.id_fields.Id)[0];
  const af = mine ? mine.fields : {};
  if (!mine) warnings.push(`Brak oceny (assessment) dla ${first.person.fields.full_name}.`);
  else if (!accepted(af)) warnings.push(`needs_summary dla ${first.person.fields.full_name} nie jest zaakceptowane (ai_status=${af.ai_status}) - pominiete.`);
  assessment = { needs_summary: accepted(af) ? af.needs_summary : '', position: af.position || first.person.fields.position || '' };
  a = { o: af.cefr_overall, r: af.cefr_range, a: af.cefr_accuracy, f: af.cefr_fluency, c: af.cefr_communication };
  const rf = first.rec.fields;
  if (!accepted(rf)) warnings.push(`Rekomendacja "${rf.title}" nie jest zaakceptowana (ai_status=${rf.ai_status}) - tekst pominiety.`);
  recommendation = accepted(rf) ? { headline: rf.headline, rationale: rf.rationale } : { headline: '', rationale: '' };
}

// pakiety: jeden wpis na slajd uzasadnienia; core bez slajdow = jeden wpis
const packages = [];
for (const rec of recs) {
  for (const core of cores.filter(c => c._rec_id === rec.id_fields.Id)) {
    const own = slides.filter(s => s._core_id === core.id_fields.Id);
    const base = { name: core.fields.title, hours: core.fields.hours };
    if (!own.length) packages.push({ ...base, title: core.fields.title, description: '' });
    for (const s of own) packages.push({ ...base, title: s.fields.title || s.fields.name, description: s.fields.description || '' });
  }
}
if (!packages.length) warnings.push('Brak wybranych pakietow core w rekomendacjach.');

// dodatki: ta sama pozycja u kilku osob = jedna linia, godziny sumowane
const others = [];
for (const sel of selOthers) {
  const v = variants.find(x => x._selected_id === sel.id_fields.Id);
  if (!v) continue;
  const hours = Number(sel.fields.hours) || 0;
  const hit = others.find(o => o.key === v.fields.key && o.name === v.fields.name);
  if (hit) hit.hours += hours;
  else others.push({ key: v.fields.key, name: v.fields.name, description: v.fields.description || '', hours });
}

const testimonials = testimonialRows.map(t => ({ content: t.fields.content, name: t.fields.client_name, position: t.fields.position }));
if (!testimonials.length) warnings.push('Brak wybranych referencji (testimonials).');

const lead = rows('Get linked source lead')[0];
const buyer = rows('Get linked buyer')[0];
const contactName = (lead && lead.fields.lead_name) || (buyer && buyer.fields.full_name) || '';

const data = {
  key: offer.cover_style || '',
  lead: { contact_name: contactName },
  offer: { date: $now.toFormat('dd.MM.yyyy'), hours: offer.hours, price: offer.total_price },
  assessment, a, recommendation,
  participants: participants.map(p => ({ full_name: p.person.fields.full_name, position: p.person.fields.position })),
  packages, others,
  testimonials,
  logo_wall: offer.logo_wall_style ? [{ key: offer.logo_wall_style }] : [],
};
if (testimonials.length) data.testimonial = testimonials[0];

return [{ json: { offer_id: offer.Id, data, flow_warnings: warnings } }];

// Render nie ustawia nazwy pliku; bierzemy tytul oferty i rozszerzenie szablonu.
const offer = $('Offer from button').first().json.offer;
const tpl = ($('Get offer template').first().json.file || [])[0];
const ext = ((tpl?.title || tpl?.url || '').split('.').pop() || 'pptx').toLowerCase();
const name = `${(offer.title || `offer-${offer.Id}`).replace(/[^\w\-. ]+/g, '_')}.${ext}`;
return $input.all().map(item => { if (item.binary?.offer) item.binary.offer.fileName = name; return item; });
